/* The same purpose string shared/Unsubscribe link signs (TASK-L187 §4). */
if (Inputs.u !== undefined && Inputs.s !== undefined) {
  Outputs.value = 'dbt-unsubscribe:v1:' + String(Inputs.u || '');
  Outputs.go();
}

/*
 * ONE PRESS FROM A LINK IN A MAIL, WITH NO SESSION (TASK-L187 §4).
 *
 * The signature is recomputed and compared in constant time. A match sets
 * `emailOptOutAt`, keeping the FIRST stamp if there is one. EVERY OUTCOME
 * ANSWERS THE SAME — a bad signature, an unknown account, a success — so this
 * public route cannot be used to learn which accounts exist. It can only ever
 * turn mail OFF: nothing here clears an opt-out.
 *
 * It runs on the page's PRESS, never on a GET (the page calls it from a button),
 * because a mail scanner follows links (L125).
 */
(async () => {
  const u = String(Inputs.u || '');
  const s = String(Inputs.s || '').toLowerCase();
  const want = String(Inputs.signature || '').toLowerCase();
  let same = s.length === want.length && want.length === 64;
  let diff = 0;
  for (let i = 0; i < want.length; i++) diff |= (s.charCodeAt(i) || 0) ^ want.charCodeAt(i);
  same = same && diff === 0;
  try {
    if (same && u) {
      const users = await Noodl.Records.query('_User', { objectId: { equalTo: u } }, { limit: 2, plain: true });
      if (users.length === 1 && !users[0].emailOptOutAt) {
        await Noodl.Records.save(u, { emailOptOutAt: new Date().toISOString() }, { className: '_User' });
      }
    } else {
      console.warn('[dbt:unsubscribe] a link that does not verify');
    }
  } catch (e) {
    console.error('[dbt:unsubscribe] ' + String((e && e.message) || e));
  }
  Outputs.done();
})();
